    for r, row in enumerate(grid):
        xs = [c for c, value in enumerate(row) if value]
        if not xs:
            continue
        for a, b in zip(xs, xs[1:]):
            if b - a == 2 and row[a] == row[b]:
                col = a + 1
                color = row[a]
                out[r][col] = color
                for rr in range(r):
                    if out[rr][col] == 0:
                        out[rr][col] = color
